import{z as i,x as d,o as E,c as A,q as l,j as s,D as e,d as t,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Masked LM","description":"","frontmatter":{"title":"Masked LM","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/masked-lm.md","filePath":"llm/masked-lm.md","lastUpdated":1791413859000}'),B={name:"llm/masked-lm.md"};function p(M,a,c,m,D,h){const o=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=l('<h1 id="masked-lm" tabindex="-1">Masked LM <a class="header-anchor" href="#masked-lm" aria-label="Permalink to &quot;Masked LM&quot;">​</a></h1><div class="epigraph"><p>随机挡住一些标记，让表示从左右两侧的未挡上下文里重建它们——预训练的是双向编码器，不是从左到右的生成器。</p><footer>—— Devlin et al., BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding, NAACL 2019</footer></div><p><a href="/llm/causal-lm">上一课</a>用 \\(p(x_t\\mid x_{\\lt t})\\) 的乘积建模文本：训练与自回归生成共享同一条件集合，每个位置一个预测，右侧永远不可见。缺口在理解侧。判断一句是否通顺、槽位是否被后半句约束，往往需要右侧；源端若也走因果链，条件生成会弱于能双向读源的编码器。本课写 Masked LM——挖掉部分 token、用双向上下文重建，预训练的是编码器表示。不重推因果分解，也不把 span 腐蚀展开成另一篇。后课 Prefix LM 默认已经读完这条去噪目标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/causal-lm">Causal LM</a>在位置 \\(t\\) 只能用 \\(x_{\\lt t}\\)，对「理解」任务不自然：判断一句是否通顺、槽位是否被后半句约束，往往需要右侧。ELMo 用双向前缀拼接近似双侧，仍不是同一套参数里的真双向交互。要让位置 \\(i\\) 的表示同时依赖左右，训练时又不能让模型直接抄 \\(x_i\\) 本身，就必须把 \\(x_i\\) 从输入里拿走或替换掉。MLM 的问题设定就是：<strong>双侧可见，但被预测的符号在输入中不可用</strong>。</p><p>若拿走的方式与微调时的输入不一致，会出现预训练—微调裂缝。BERT 用 <code>[MASK]</code> 替换，而微调几乎从不出现 <code>[MASK]</code>。这是 MLM 相对 Causal LM 多出来的匹配问题：Causal LM 的训练符号与生成符号是同一套。</p><p><span class="marginnote">直觉类比：MLM 就是做完形填空——文章挖掉几个空，考生看完整段再作答；Causal LM 像词语接龙——只能说下一个词，永远不许偷看后面。填空练出来的是「理解」（判断这个词该是什么），接龙练出来的是「续写」。BERT 靠前者，GPT 靠后者。</span></p><h3 id="不能看见答案-但要看见两侧" tabindex="-1">不能看见答案，但要看见两侧 <a class="header-anchor" href="#不能看见答案-但要看见两侧" aria-label="Permalink to &quot;不能看见答案，但要看见两侧&quot;">​</a></h3><p>实现上不是把该位置从序列里删掉（那会让长度与对齐错乱），而是保留占位。占位符携带「这里有东西」的位置信息，不携带词表身份。模型必须从 \\(x_{\\setminus i}\\) 恢复身份。若占位符偶尔仍是原词，裂缝会小一些，但任务会变容易，需要按概率混合，见下文 BERT 的 80/10/10。</p><p><span class="marginnote">NSP（下一句预测）是 BERT 原文里的第二个目标，不是 MLM 的定义。后来不少工作弱化或去掉 NSP。写 Masked LM 时应把「挖词重建」与「句对分类」分开；本篇以挖词为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Devlin 等人的标准配方：选中约 <strong>15%</strong> 的 WordPiece token 作为预测对象。对被选中的位置，输入替换规则为：<strong>80% 换成 <code>[MASK]</code>，10% 换成随机词表项，10% 保持原词</strong>。损失只在被选中的位置上计算交叉熵，未选中位置不贡献 MLM 损失。编码器是完整的双向自注意力，没有因果上三角。位置编码为可学习绝对位置，最长 512，这是 BERT 原文设定，不是 MLM 目标的必然部分。</p><p>15% 是在「一次提供足够多的训练信号」和「留下足够多的未损上下文」之间的折中。腐蚀太低，每个 batch 的有效标签太少；腐蚀太高，句子被挖空，双侧上下文本身残缺，任务退化成乱猜。随机 10% 与保持 10% 是为了让模型不能把 <code>[MASK]</code> 当成「只有这里才需要从上下文取词」的作弊特征，微调时任意位置都可能被查询。</p><p><span class="marginnote">把 80/10/10 代入一个具体例子：一句 100 个 token 的文本，按 15% 选出约 15 个位置；其中约 12 个换成 <code>[MASK]</code>，1 到 2 个换成随机词，1 到 2 个保持原词。随机替换意味着输入里可能出现「假装是答案」的错词——模型必须学会对照上下文判断「眼前这个词可信吗」，这正是微调时遇到真实输入的状态。</span></p>',14)),(E(),s(n,null,{default:e(()=>[r(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8E%9F%E5%8F%A5%22%5D%20--%3E%20P%5B%22%E9%80%89%E7%BA%A6%2015%25%20%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20P%20--%3E%20M%5B%2280%25%20%5BMASK%5D%20%2F%2010%25%20%E9%9A%8F%E6%9C%BA%20%2F%2010%25%20%E5%8E%9F%E8%AF%8D%22%5D%0A%20%20M%20--%3E%20ENC%5B%22%E5%8F%8C%E5%90%91%20Transformer%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20ENC%20--%3E%20H%5B%22%E5%90%84%E4%BD%8D%E7%BD%AE%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20H%20--%3E%20L%5B%22%E5%8F%AA%E5%9C%A8%E8%A2%AB%E9%80%89%E4%BD%8D%E7%BD%AE%E4%B8%8A%E5%AF%B9%E8%AF%8D%E8%A1%A8%E5%88%86%E7%B1%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="微调时目标消失" tabindex="-1">微调时目标消失 <a class="header-anchor" href="#微调时目标消失" aria-label="Permalink to &quot;微调时目标消失&quot;">​</a></h3><p>预训练结束，<code>[MASK]</code> 头往往丢掉或不用，改在 <code>[CLS]</code> 或各 token 上接分类 / 抽取头。此时注意力仍是双向，输入不再腐蚀。MLM 的作用是把编码器训成一套通用初始化。这与 Causal LM 继续用同一个下一个词头做生成不同。若强行用 MLM 模型逐步生成，需要迭代填掩码或改成非自回归解码，延迟与质量都不是 Causal LM 的路径。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>双向注意力让位置 \\(i\\) 的查询可以打到左右任意未损位置的键，表示是条件于几乎整句的。被 <code>[MASK]</code> 的位置仍产生查询，但自己的值向量是掩码嵌入，不泄漏原词。随机替换引入噪声，迫使表示对「输入里这个词不一定对」鲁棒。保持原词的 10% 则提供一条捷径：有时身份就在输入里，模型要学会何时相信输入、何时相信上下文——微调时全部是「相信输入」。</p><p>与 Causal LM 比，每个被选位置的条件信息更多（双侧），但每个序列只有约 15% 的位置给梯度。BERT-base 用这一点在 GLUE、SQuAD 一类理解任务上建立了预训练标准。生成任务上，缺了从左到右的因式分解，只能另接解码器或改掩码。UniLM 后来用同一套参数切换掩码来同时做理解与生成，那已是 Prefix / 统一掩码，不是纯 MLM。</p>',5)),(E(),s(n,null,{default:e(()=>[r(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%90%8C%E4%B8%80%E5%8F%A5%E8%BE%93%E5%85%A5%22%5D%20--%3E%20C%5B%22Causal%20LM%22%5D%0A%20%20X%20--%3E%20B%5B%22Masked%20LM%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E6%AF%8F%E4%B8%AA%E4%BD%8D%E7%BD%AE%E5%8F%AA%E8%A7%81%E5%B7%A6%E4%BE%A7%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%AF%8F%E4%BD%8D%E7%BD%AE%E9%83%BD%E6%9C%89%E6%A2%AF%E5%BA%A6%20%E7%9B%B4%E6%8E%A5%E5%8F%AF%E7%94%9F%E6%88%90%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E8%A2%AB%E9%80%89%E4%BD%8D%E7%BD%AE%E6%94%B9%E5%86%99%20%E5%85%B6%E4%BD%99%E5%8F%8C%E4%BE%A7%E5%85%A8%E5%8F%AF%E8%A7%81%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E4%BB%85%E7%BA%A6%2015%25%20%E4%BD%8D%E7%BD%AE%E6%9C%89%E6%A2%AF%E5%BA%A6%20%E6%98%AF%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p><span class="marginnote">常见误区：以为 BERT 这类 MLM 模型也能像 ChatGPT 那样一个词一个词往外写。实际上双向编码器没有「从左到右逐词生成」的分解——它所有位置是一起算的，硬要生成只能反复填空或另接解码器，又慢又别扭。理解任务找 BERT 一族，开放生成找 GPT 一族，是两条训练目标分出的分工。</span></p><p><span class="marginnote">BERT 的 15% 作用在 WordPiece 上，不是作用在空白分词的词上。一个英文词可能对应多个子词，被选中的是子词。中文若按字或按 SentencePiece，同样的 15% 对应的语言跨度不同，不能直接说「每句遮 15% 的词」。</span></p><h3 id="裂缝的机制" tabindex="-1">裂缝的机制 <a class="header-anchor" href="#裂缝的机制" aria-label="Permalink to &quot;裂缝的机制&quot;">​</a></h3><p>训练时模型看见大量 <code>[MASK]</code>，学会「掩码位=要填的槽」。微调没有槽，表示分布偏移。80/10/10 把一部分训练位置改成看起来像微调的输入，减轻偏移，不能消灭。后续有整词掩码、span 腐蚀，改的是挖哪些位置，裂缝的根源仍在：预训练输入含损坏，下游输入通常不损坏。T5 把损坏改成显式的哨兵再生成 span，等于把 MLM 改写成编码器—解码器的去噪，裂缝形态又变一次。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MLM 编码器不是聊天模型。双向表示适合分类、抽取、句向量，不适合直接做开放生成。长度 512 是 BERT 原文的工程选择；把 MLM 接到长上下文要另解位置与算力，目标本身不提供长度外推。15% 与 80/10/10 是被广泛复用的超参，不是信息论最优；换词表、换语言、换 span 都应重扫腐蚀率。</p><p>不要把任意「输入里有洞」都叫 BERT。Causal LM 的填充式提示、Prefix LM 的源端全可见、UL2 的混合去噪，各自条件集合不同。引用应写 Devlin 等，<em>BERT</em>，NAACL 2019（及 2018 预印本）。不要把 RoBERTa 去掉 NSP、动态掩码的改进写进 BERT 定义——那是后续工作。</p><p><span class="marginnote">推理期若仍随机掩码再重建，那是在做填空或数据增强，不是 BERT 微调标准路径。标准路径是全可见输入 + 任务头。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Masked LM 挖掉部分 token、用双向上下文重建，预训练的是编码器表示。</li><li>BERT 配方：约 15% 位置，80% <code>[MASK]</code>、10% 随机、10% 保持；损失只在这些位置上。</li><li>相对 Causal LM：条件更全、监督更稀、生成不能直接自回归。</li><li><code>[MASK]</code> 造成预训练与微调输入不一致；80/10/10 减轻但不消除。</li><li>NSP 不是 MLM 的一部分；下游通常丢掉掩码头，改接任务头。</li><li>出处：Devlin et al.，<em>BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding</em>，NAACL 2019。</li></ul>',10))])}const u=i(B,[["render",p]]);export{T as __pageData,u as default};
